import { prisma } from '@/lib/prisma';

// Find all customers who have at least one completed order over $500
const vipCustomers = await prisma.customer.findMany({
  where: {
    orders: {
      some: {
        status: 'COMPLETED',
        totalAmount: { gte: 500 }
      }
    }
  },
  include: {
    _count: {
      select: { orders: true } // Efficiently returns order count without loading rows
    }
  }
});
